+    TORCH_CHECK_DTYPE(k_out, kInt);
+    TORCH_CHECK_DTYPE(k_out_scales, kHalf);
+    TORCH_CHECK_DTYPE(v_in, kHalf);
+    TORCH_CHECK_DTYPE(v_out, kInt);
