+    int v_bits = v_out.size(2) / warps_per_token;
+
+    int bsz = block_table.size(0);
+    int blocks_per_seq = block_table.size(1);
+
+    dim3 blocks(tb_per_token, seq_len, bsz);
+    dim3 threads(32 * tb_usage);
+
