+                    (const uint32_t*) cache_seqlens.data_ptr(),
+                    (const uint32_t*) block_table.data_ptr(),
+                    page_size,
+                    blocks_per_seq,
+                    dim
+                );
+            }
+        });
+    });
+    cuda_check(cudaPeekAtLastError());
+}
